<?php
declare(strict_types=1); require __DIR__ . '/app/auth.php'; exigirEquipe(); require __DIR__ . '/app/db.php';
$id=(int)($_GET['id']??0); $pdo=banco(); $q=$pdo->prepare('SELECT * FROM orcamentos WHERE id=?');$q->execute([$id]);$o=$q->fetch(); if(!$o)exit('Orçamento não encontrado.'); if(in_array($o['status'], ['rascunho','pronto_para_envio'], true)) exit('Edite este orçamento diretamente antes de enviá-lo.');
$pdo->beginTransaction(); $origem=$o['origem_id']?:$o['id']; $codigo='ORC-'.date('Ymd-His'); $rev=(int)$o['revisao']+1;
$i=$pdo->prepare('INSERT INTO orcamentos (codigo,cliente_id,local_obra,cidade,bairro,endereco,complemento,cep,validade,prazo_dias,status,revisao,origem_id,total_centavos) VALUES (?,?,?,?,?,?,?,?,?,?,"rascunho",?,?,?)');$i->execute([$codigo,$o['cliente_id'],$o['local_obra'],$o['cidade'],$o['bairro'],$o['endereco'],$o['complemento'],$o['cep'],$o['validade'],$o['prazo_dias'],$rev,$origem,$o['total_centavos']]);$novo=(int)$pdo->lastInsertId();
$it=$pdo->prepare('INSERT INTO itens_orcamento (orcamento_id,categoria,descricao,unidade,quantidade,periodo_quantidade,periodo_tipo,valor_tabela_centavos,valor_unitario_centavos,subtotal_centavos) SELECT ?,categoria,descricao,unidade,quantidade,periodo_quantidade,periodo_tipo,valor_tabela_centavos,valor_unitario_centavos,subtotal_centavos FROM itens_orcamento WHERE orcamento_id=?');$it->execute([$novo,$id]); if ($o['status'] === 'aguardando_cliente') $pdo->prepare('UPDATE orcamentos SET status="negociacao" WHERE id=?')->execute([$id]); $pdo->commit();header('Location: orcamento.php?id='.$novo);
